"""Small full-feature gate; select only a cutoff preserving all dev accepted predictions."""
from pathlib import Path
import sys,json,time
import numpy as np,polars as pl,lightgbm as lgb
R=Path(__file__).resolve().parents[2];O=Path(__file__).parent;P=R/'experiments/astra_011';S=R/'experiments/astra_013';sys.path.insert(0,str(R/'experiments/astra_engine'));import context as C
from reference_guard import accepted
key=['s1','src','eid'];cfg=json.loads((S/'expanded_macro_decision.json').read_text());cfg['reference_guard']={'strong':.9,'margin':.01};features=cfg['features'];tr=pl.read_parquet(P/'mined_train.parquet').join(pl.read_parquet(S/'train_extra.parquet'),on=key,validate='1:1',maintain_order='left').join(pl.read_parquet(P/'train/ntrue.parquet'),on='s1',maintain_order='left');dev=C.add(pl.read_parquet(P/'dev/parts/*.parquet')).join(pl.read_parquet(S/'dev_extra.parquet'),on=key,validate='1:1');t=time.time();m=lgb.LGBMClassifier(objective='binary',learning_rate=.1,num_leaves=31,min_child_samples=80,colsample_bytree=.95,n_estimators=250,n_jobs=2,random_state=20261002,verbosity=-1);m.fit(tr.select(features).to_numpy(order='c'),tr['label'].to_numpy(),sample_weight=tr['_weight'].to_numpy()/np.maximum(tr['ntrue'].to_numpy(),1)**.5,feature_name=features);m.booster_.save_model(str(O/'full_feature_gate.txt'));p=m.booster_.predict(dev.select(features).to_numpy(order='c'),num_threads=2);g=dev.select(key).with_columns(pl.Series('gate',p.astype('float32')));g.write_parquet(O/'dev_gate_scores.parquet');s=pl.read_parquet(S/'guard_macro/scored.parquet').join(g,on=key,validate='1:1');sel=accepted(s,cfg);rows=[]
for threshold in [0.,.000001,.000005,.00001,.00002,.00005,.0001,.0002,.0005,.001,.002,.005,.01]:
 dropped=sel.filter(pl.col('gate')<threshold);rows.append({'threshold':threshold,'expensive_pairs':s.filter(pl.col('gate')>=threshold).height,'accepted_dropped':dropped.height,'true_dropped':int(dropped['label'].sum()),'false_dropped':dropped.height-int(dropped['label'].sum())})
pl.DataFrame(rows).write_csv(O/'gate_ablation.csv');valid=[r for r in rows if r['accepted_dropped']==0];best=valid[-1];(O/'gate_selection.json').write_text(json.dumps({'selection':best,'features':features,'runtime':time.time()-t,'selection_rule':'largest predeclared cutoff preserving every dev accepted pair; no holdout used'},indent=2));print(rows,flush=True)
